import asyncio

attempts = []

async def flaky():
    attempts.append(1)
    if len(attempts) < 3:
        raise ConnectionError("нет связи")
    return "успех"

async def retry(func, tries=5, base=0.01):
    for i in range(tries):
        try:
            return await func()
        except ConnectionError:
            if i == tries - 1:
                raise
            await asyncio.sleep(base * 2 ** i)

print(asyncio.run(retry(flaky)), len(attempts))
